def transform(grid):
    # For each outlined rectangle, fill its interior based on shape parity:
    # odd-by-odd interior -> 7; otherwise -> 2.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(x==v for row in grid for x in row))
    for color in set(v for row in grid for v in row)-{bg}:
        for r0 in range(h):
            for r1 in range(r0+2,h):
                for c0 in range(w):
                    for c1 in range(c0+2,w):
                        if all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1)):
                            inside=[grid[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
                            if inside and all(v==bg for v in inside):
                                fill=7 if ((r1-r0-1)*(c1-c0-1)) % 2 == 1 else 2
                                for r in range(r0+1,r1):
                                    for c in range(c0+1,c1): out[r][c]=fill
    return out
def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {v: sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    background = max(counts, key=counts.get)
    separator_col = next(c for c in range(w)
                         if len({grid[r][c] for r in range(h)}) == 1
                         and grid[0][c] != background)
    separator = grid[0][separator_col]
    object_color = next(v for v in counts if v not in (background, separator))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == object_color]
    left, right = min(c for r, c in cells), max(c for r, c in cells)

    # Shift the object so its nearest edge is one cell from the divider.
    if right < separator_col:
        shift = separator_col - 1 - right
        stripe = left + shift - 1
    else:
        shift = separator_col + 1 - left
        stripe = right + shift + 1

    for r, c in cells:
        out[r][c] = background
    for r, c in cells:
        out[r][c + shift] = object_color
    if 0 <= stripe < w:
        for r in range(h):
            out[r][stripe] = 8
    return out

